parameters.functionScript:
const items = Inputs.items || [];
if (!items.length) {
  Outputs.listText = 'No saved articles yet.';
  return;
}
Outputs.listText = items.map(i => {
  const d = i.savedAt ? new Date(i.savedAt) : null;
  const dateStr = d ? d.toLocaleDateString() : '';
  return (i.title || 'Untitled') + '  —  ' + dateStr;
}).join('\n');
